        .reduce((acc, col) => ({
          ...acc,
          [col.title]: {
            ...col,
            chats: this.files.filter(f => f.column?.title === col.title)
          }
        }), {})
    },
    profiles() {
      return this.files?.map(f => f.profiles)
        .reduce((a, b) => [...a, ...b])
        .reduce((acc, profile) => ({ ...acc, [profile.name]: profile }), {})
    },
    messages() {
