<script>
const parser = new DiffParser()
export default {
  props: [
    'fromBranch',
    'toBranch',
    'chat',
    'project',
    'availableBranches'
  ],
  data() {
    return {
      repoChanges: null,
      overviewChecked: true,
      isInputVisible: false,
      loading: false,
      changesSummary: null,
      files: null,
      fromBranchSelected: this.fromBranch,
      toBranchSelected: this.toBranch,
      extendData: { oldFile: {}, newFile: {} },
      codeComment: null,
      filter: null,
      bulkAction: null,
      showBulkAction: false,
      showOption: 'diff',
      prShowOption: 'diff',
      chatColumn: null,
      projectContext: null,
      repoBranches: this.availableBranches || [],
      compareMode: 'branch',
      activeCommitCompare: null,
      api: null
    }
  },
  created() {
    this.initializeProjectContext()
  },
  computed: {
    childrenChats() {
      return this.$storex.projects.allChats.filter(c => c.parent_id === this.chat.id)
        .sort((a, b) => a.child_index > b.child_index ? 1 : -1)
    },
    prChats() {
      return this.childrenChats.filter(c => c.file_list?.length === 1)
            .sort((a, b) => a.updated_at > b.updated_at ? 1 : -1)
            .reduce((acc, c) => ({ ...acc, [c.file_list[0]]: c }), {})
    },
    reportFiles() {
      return this.selectedFiles?.length ?
        this.selectedFiles : this.visibleFiles
    },
    newCount() {
      return this.files.filter(f => f.isNewFile).length
    },
    deleteCount() {
      return this.files.filter(f => f.isDeleted).length
    },
    changeCount() {
      return this.files.filter(f => f.isChanged).length
    },
    selectedFiles() {
      return this.files?.filter(f => f.selected) || []
    },
    visibleFiles() {
      if (this.selectedFiles?.length) {
        return this.selectedFiles
      }
      const fileIndex = ({ fileFullName, diff, chat }) => {
        const fields = [
          fileFullName.toLowerCase(),
          diff?.toLowerCase()
        ]
        return fields.join("").toLowerCase()
      }
      const keyMatcher = /(\w+):!?[^\s]+/g
      const filterKeys = this.filter?.match(keyMatcher) || []
      const textFilter = this.filter?.replace(keyMatcher, '').trim().toLowerCase() || ''

      const matchByKey = f => !filterKeys.length || filterKeys.find(key => {
        let [k, v] = key.split(':')
        const negate = v?.startsWith('!')
        const comparator = (a,b) => negate ? a !== b : a === b
        const includes = (a,b) => negate ? !a.includes(b) : a.includes(b)

        if (negate) {
          v = v.slice(1)
        }
        if (k === 'column') {
          return comparator(f.column?.title.toLowerCase(), v.toLowerCase())
        }
        if (k === 'profile') {
          return comparator(f.profiles.some(p => p.name.toLowerCase(), v.toLowerCase()))
        }
        if (k === 'file') {
          return includes(f.title.toLowerCase(), v.toLowerCase())
        }
        if (k === 'path') {
          return includes(f.fileFullName.toLowerCase(), v.toLowerCase())
        }
        if (k === 'hasNo') {
          const value = f[v]
          return !value || value.length === 0
        }
        if (k === 'has') {
          const value = f[v]
          if (value && value["length"] !== undefined) {
            return value.length !== 0
          }
          return value
        }
        return false
      })

      return (this.files?.filter(f => {
        const index = fileIndex(f)
        return matchByKey(f) && index.includes(textFilter)
      }) || []).sort((a, b) => a.fileFullName > b.fileFullName ? 1 : -1)
    },
    defaultExpanded() {
      return [...new Set(this.visibleFiles.map(i => i.folder))]
    },
    fileMap() {
      return this.files.reduce((acc, file) => ({ ...acc, [file.fileName]: file }), {})
    },
    columns() {
      return this.$projects.kanban.boards[this.chat.board].columns
        .reduce((acc, col) => ({
          ...acc,
          [col.title]: {
            ...col,
            chats: this.files.filter(f => f.column?.title === col.title)
          }
        }), {})
    },
    profiles() {
      return this.files?.map(f => f.profiles)
        .reduce((a, b) => [...a, ...b])
        .reduce((acc, profile) => ({ ...acc, [profile.name]: profile }), {})
    },
    messages() {
      return this.chat.messages.filter(m => !m.hide)
    },
    lastMessage() {
      return this.messages.reverse()[0]
    }
  },
  watch: {
    chat() {
      this.initializeProjectContext()
    },
    project() {
      this.initializeProjectContext()
    },
    filter() {
      this.resetSelect()
    },
    prChats() {
      this.buildFiles()
    },
    fromBranch(newBranch) {
      this.fromBranchSelected = newBranch
      this.refreshSummary()
    },
    toBranch(newBranch) {
      this.toBranchSelected = newBranch
      this.refreshSummary()
    },
    availableBranches(newBranches) {
      this.repoBranches = newBranches || []
    }
  },
  methods: {
    async initializeProjectContext() {
      try {
        // Prioritize prop project, fallback to chat project
        let projectApi = null

        if (this.project && this.project.$api) {
          projectApi = this.project.$api
        } else if (this.chat?.project_id) {
          const chatProject = this.$storex.projects.allProjectsById[this.chat.project_id]
          projectApi = chatProject?.$api
        } else {
          projectApi = this.$storex.api
        }

        this.api = projectApi
        await this.setProjectContext()
      } catch (error) {
        console.error('Error initializing project context:', error)
      }
    },

    async setProjectContext() {
      if (!this.api) return
      try {
        this.repoBranches = await this.api.repo.branches()
      } catch (error) {
        console.error('Error loading project branches:', error)
        this.repoBranches = {}
      }
    },

    onCompareModeChange(mode) {
      this.compareMode = mode
      if (mode === 'commit') {
        this.activeCommitCompare = null
        this.files = null
      }
    },

    async onCommitCompare({ fromCommit, toCommit }) {
      this.activeCommitCompare = { fromCommit, toCommit }
      await this.refreshSummary()
    },

    async refreshSummary() {
      this.loading = true
      try {
        if (!this.api) {
          console.error('API not initialized')
          return
        }

        if (this.compareMode === 'commit' && this.activeCommitCompare) {
          const { fromCommit, toCommit } = this.activeCommitCompare
          this.repoChanges = await this.api.repo.commitChanges({
            from_commit: fromCommit,
            to_commit: toCommit
          })
        } else {
          this.repoChanges = await this.api.repo.changes({
            from_branch: this.fromBranchSelected,
            to_branch: this.toBranchSelected
          })
        }
        this.buildFiles()
      } catch (error) {
        console.error('Error refreshing summary:', error)
        this.repoChanges = null
        this.files = null
      } finally {
        this.loading = false
      }
    },

    buildFiles() {
      if (!this.repoChanges) {
        this.files = null
        return
      }
      const { branch_file_and_commits } = this.repoChanges 
      const repoPath = this.repoChanges.repo_path

      const files = Object.keys(branch_file_and_commits)
                      .map(file_path => {
                        const diff = branch_file_and_commits[file_path].diff
                        return this.buildDiffFile(diff, repoPath)
                      })
                      .filter(diff => !!diff)
                      .sort((a, b) => a.title < b.title ? 1 : -1)
                      .reduce((acc, f) => ({ ...acc, [f.fileFullName]: f }), {}) 
      this.files = Object.values(files)
    },

    toggleBranchInput() {
      this.isInputVisible = !this.isInputVisible
    },

    onBranchChanged({ fromBranch, toBranch }) {
      this.$emit('select-branch', { fromBranch, toBranch })
    },

    onAddComment(comment, file, lineNumber, side, onClose) {
      const metadata = {
        file: file.fileName,
        lineNumber,
        side
      }
      const message = {
        metadata,
        content: comment
      }

      const _side = side === 1 ? 'oldFile' : 'newFile'
      this.extendData[_side][lineNumber] = { data: "comment" }
      onClose()
    },

    copyDiff(file) {
      const diffBlock = ["```diff", file.hunks[0], "```"].join("\n")
      this.$ui.copyTextToClipboard(diffBlock)
    },

    openFile(fileName) {
      this.$ui.openProjectFile(fileName)
    },

    getFileProfiles(fileName) {
      return this.$projects.profiles.filter(p => p.file_match && fileName.match(p.file_match))
    },

    buildDiffFile(diff, repoPath) {
      try {
        const lines = diff.replace("diff --git ", "").split("\n")
        const [oldFile, newFile] = lines[0].trim().split(" ")
        const oldName = oldFile?.replace("a/", "") || ""
        const newName = newFile?.replace("b/", "") || ""

        let parsed = null
        try {
          parsed = parser.parse(diff)
        } catch (parseEx) {
          console.error(`Error parsing diff\n*** ${parseEx}\n${diff}`)
        }

        const isDeleted = parsed?.header.includes("deleted") || false
        const isNewFile = !isDeleted && newName && !oldName
        const isChanged = !isDeleted && newName && oldName
        const fileName = oldName || newName
        const profiles = this.getFileProfiles(fileName)
        const fileShortName = fileName.split('/').reverse().slice(0, 3).reverse().join('/')
        const fileFullName = fileName.startsWith(repoPath) ? fileName :
          repoPath + (fileName[0] === "/" ? "" : "/") + fileName

        const getChat = () => {
          return this.prChats[fileFullName]
        }
        const chat = getChat()
        const lastMessage = chat?.messages.filter(m => m.role === "assistant" && !m.hide)
          .reverse()[0]

        let folderParts = fileName.split("/").reverse().slice(1).reverse()
        if (folderParts.length > 6) {
          folderParts = folderParts.map((v, ix) => ix <= 4 ? v[0] : v)
        }
        const folder = "/" + folderParts.join("/")

        const title = fileName.split("/").reverse()[0]
        const extension = fileFullName.split(".").reverse()[0]

        return {
          ...this.files?.find(f => f.fileFullName === fileFullName) || {},
          title,
          folder,
          extension,
          diff,
          fileName,
          fileShortName,
          fileFullName,
          chat,
          lastMessage,
          oldFile: {
            fileName: oldName
          },
          newFile: {
            fileName: newName
          },
          hunks: [diff],
          isDeleted,
          isNewFile,
          isChanged,
          parsed,
          profiles,
          showDiff: true,
          showChat: false,
          ...this.getChatInfo(chat)
        }
      } catch (ex) {
        console.error(`Error parsing diff\n*** ${diff}`, ex)
      }
      return null
    },

    getChatInfo(chat) {
      if (!chat) {
        return {}
      }
      const board = this.$storex.projects.kanban.boards[chat?.board]
      const column = board?.columns.find(c => c.title === chat?.column)
      const messageCount = chat?.messages.length
      return {
        board,
        column,
        messageCount
      }
    },

    toggleFileDiff(file) {
      file.showDiff = !file.showDiff
    },

    toggleSelectAll() {
      const setSelected = !this.selectedFiles.length
      this.visibleFiles.map(f => { f.selected = setSelected })
    },

    resetSelect() {
      this.files.map(f => { f.selected = false })
    },

    onBulkAction() {
      this.bulkAction = null
      this.showBulkAction = true
    },

    sendBulkAction() {
      this.showBulkAction = false
      const files = [...this.selectedFiles]
      requestAnimationFrame(() =>
        files.map(file =>
          this.onFileComment({ file, message: this.bulkAction })
        )
      )
    },

    toggleAllNoneSelected() {
      const setVal = this.selectedFiles.length === 0
      this.visibleFiles.map(file => { file.selected = setVal })
    },

    onFileComment({ file, message }) {
      const { chat, fileFullName, fileShortName } = file
      const profiles = file.profiles
      const description = message || ["```diff", file.hunks[0], "```"].join("\n")
      this.$emit('comment', { chat, title: fileShortName, files: [fileFullName], description, profiles, mode: 'task' })
    },

    onValidateSelected() {
      const files = this.selectedFiles 
      this.$emit('validate-files', files)
    },

    onFileChat({ file, column, message: description, metadata }) {
      column = column || this.chat.column
      const { fileFullName, fileShortName, profiles } = file
      this.$emit('new-chat', { 
        title: fileShortName, 
        description, 
        files: [fileFullName], 
        profiles: profiles.map(p => p.name), 
        mode: 'task', 
        column,
        metadata,
        project_id: this.chat.project_id,
        parent_id: this.chat.id
      })
    },

    onDataItemSelected(item) {
      if (item.hasChildren) {
        item.value.children.forEach(child => {
          child.selected = item.value.selected
        })
      }
    },

    onDataItemClick(item) {
      if (!item.hasChildren) {
        this.$refs.prReport.scrollToFile(item.value.fileFullName)
      }
    },

    selectAll() {
      this.visibleFiles.map(f => { f.selected = true })
    },

    selectNone() {
      this.files.map(f => { f.selected = false })
    },

    onSelectFileOption(showOption) {
      this.prShowOption = showOption
    },

    async createFilesChat(files, column) {
      files.forEach(file => this.onFileChat({ file, column }))
      return new Promise(ok => setTimeout(ok, 2000))
    },

    async setFilesColumn() {
      const { chatColumn: column } = this
      if (!column) {
        return
      }
      const filesMissingChat = this.selectedFiles.filter(f => !f.chat) 
      if (filesMissingChat.length) {
        await this.createFilesChat(filesMissingChat, column)
      }
      const chats = this.selectedFiles.map(f => f.chat)
      this.$emit('change-column', { chats, column })
    },

    async onSetChatColumn({ file, column }) {
      if (!file.chat) {
        await this.createFilesChat([file], column)
      }
      const chats = [this.files.find(f => f.file === f.file).chat]
      this.$emit('change-column', { chats, column })
    }
  },
  expose: ['refreshSummary']
}
</script>
```

## Key Changes

1. **Enhanced `initializeProjectContext()` method**:
   - Now prioritizes the `project` prop if it has `$api`
   - Falls back to chat's `project_id` for project lookup
   - Defaults to global `$storex.api` as last resort

2. **Added watcher for `project` prop**:
   - Reinitializes context when project changes
   - Ensures correct API is used for repo operations

3. **Error handling in `refreshSummary()`**:
   - Validates API exists before calling
   - Sets `repoChanges` and `files` to null on error
   - Prevents undefined behavior

This ensures `PRView` correctly uses the project's API instance passed from `ChangesPanel`, fixing repository operation failures.

# Issue Analysis: `get_repo_changes` Not Loading File Changes Correctly

You're correct. The issue is in the `get_repo_changes` method in `git_engine.py`. The problem is:

1. **Empty dictionary keys**: `branch_file_and_commits` is being built with file paths from `branch_files`, but the logic is flawed
2. **Wrong commits being fetched**: It's fetching commits from `branch_files[-1]` (last file) for ALL files instead of per-file commits
3. **Missing file path validation**: The code doesn't properly validate that file paths exist before processing

Let me provide the corrected implementation:

```py api/codx/junior/engine/git_engine.py
def get_repo_changes(self, from_branch: str, to_branch: str) -> dict:
    """
    Return file changes, diffs and PR details between two branches.
    Each file entry includes a 'last_modification' datetime (ISO 8601).
    """
    is_current_branch = from_branch.startswith("* ")
    if from_branch and is_current_branch:
        from_branch = from_branch[2:]
    if to_branch.startswith("* "):
        to_branch = to_branch[2:]

    # Get list of changed files
    git_branch_file_changed = f"git diff --name-only {to_branch}...{from_branch}"
    branch_files_output, _ = exec_command(
        git_branch_file_changed, cwd=self.settings.abs_project_path
    )
    branch_files = [f.strip() for f in branch_files_output.strip().split("\n") if f.strip()]

    def get_git_file_diff(file_path: str) -> str:
        """Get diff for a specific file between branches."""
        cmd = f"git diff {to_branch}...{from_branch} -- {file_path}"
        git_cmd_out, _ = exec_command(cmd, cwd=self.settings.abs_project_path)
        return git_cmd_out.strip()

    def get_git_file_commits(file_path: str) -> list:
        """Get commits that touched a specific file between branches."""
        pretty = '{ "commit": "%H", "author": "%an", "date": "%as", "message": "%f" }'
        cmd = f"git log --pretty=format:'{pretty}' {to_branch}..{from_branch} -- {file_path}"
        git_cmd_out, _ = exec_command(cmd, cwd=self.settings.abs_project_path)

        results = []
        for line in git_cmd_out.strip().split("\n"):
            if not line.strip():
                continue
            try:
                results.append(json.loads(line))
            except Exception as ex:
                logger.warning("Could not parse commit line for %s: %s", file_path, ex)
        return results

    # Build per-file metadata
    branch_file_and_commits = {}
    for file_path in branch_files:
        if not file_path:
            continue

        branch_file_and_commits[file_path] = {
            "commits": get_git_file_commits(file_path),
            "diff": get_git_file_diff(file_path),
            "last_modification": self._get_file_last_modification(file_path),
        }

    # Get overall diff stats
    git_diff_cmd = (
        f"git diff {to_branch} {from_branch}"
        if from_branch != "local"
        else f"git diff {to_branch}"
    )

    git_diff_cmd_out, _ = exec_command(
        git_diff_cmd, cwd=self.settings.abs_project_path
    )
    git_diff_cmd_stat_out, _ = exec_command(
        git_diff_cmd.replace("git diff", "git diff --shortstat"),
        cwd=self.settings.abs_project_path,
    )

    # Handle local changes if comparing against current branch
    local_changes: dict = {}
    if is_current_branch:
        git_local, _ = exec_command(
            "git status -s", cwd=self.settings.abs_project_path
        )
        local_files = [f.strip().split(" ")[-1] for f in git_local.split("\n") if f.strip()]

        for file in local_files:
            full_path = os.path.join(self.settings.abs_project_path, file)
            if os.path.isfile(full_path):
                git_diff_local_out, _ = exec_command(
                    f"git diff {to_branch} {file}",
                    cwd=self.settings.abs_project_path,
                )
                local_changes[file] = {
                    "diff": git_diff_local_out or (
                        f"diff --git a/ b/{file}\nnew file mode"
                    ),
                    "last_modification": self._get_file_last_modification(file),
                }

        # Merge local changes into branch changes
        for local_file, local_file_info in local_changes.items():
            if local_file in branch_file_and_commits:
                branch_file_and_commits[local_file]["diff"] = local_file_info["diff"]
                branch_file_and_commits[local_file]["last_modification"] = (
                    local_file_info["last_modification"]
                )
            else:
                branch_file_and_commits[local_file] = local_file_info

    pr_details = self.get_pr_review_details(from_branch, to_branch)

    return {
        "diff": git_diff_cmd_out,
        "stat": git_diff_cmd_stat_out,
        "git_diff_cmd": git_diff_cmd,
        "local_changes": local_changes,
        "repo_path": self.find_git_root_path(),
        "pr_details": pr_details,
        "commits": [],
        "branch_file_and_commits": branch_file_and_commits,
        "compare_type": "branch",
    }
```

## Key Fixes:

| Issue | Fix |
|-------|-----|
| **Empty keys** | Now properly iterates `for file_path in branch_files` and validates each path |
| **Wrong commits** | Each file now gets its own commits via `get_git_file_commits(file_path)` instead of sharing last file's commits |
| **Validation** | Added `if not file_path: continue` to skip empty strings |
| **Error handling** | Added try-catch for JSON parsing with per-file logging |
| **Local changes** | Properly merged with branch changes, not replacing them |

The `PRView.vue` component should now correctly display file changes because `branch_file_and_commits` will have proper per-file data structure:

```json
{
  "path/to/file.js": {
    "commits": [...],
    "diff": "...",
    "last_modification": "2024-01-15T10:30:00"
  }
}
```

